56	        $categoryA = TagCategory::create(['name' => ['it' => 'Categoria A'], 'tag_group_id' => $groupA->id]);
57	        $tagA1 = Tag::create(['name' => ['it' => 'Tag A1'], 'slug' => ['it' => 'tag-a1'], 'tag_category_id' => $categoryA->id]);
